+   const HChar* p;
+
+   for (p = name; *p != '\0'; p++) {
+      HChar c = *p;
+      if (c == ';' || c == ' ' || c == '\t' || c == '\n' || c == '\r') {
+         VG_(fprintf)(fp, "_");
+      } else {
+         VG_(fprintf)(fp, "%c", c);
