+                (unsigned long long)stats->writes.accesses,
+                read_stride, pattern_name(stats->reads.pattern),
+                write_stride, pattern_name(stats->writes.pattern));
+   }
+}
+
+static void ma_fini(Int exitcode)
+{
+   print_summary();
+   write_flamegraph_file();
+   (void)exitcode;
+}
+
