170	static void add_stride_sample(AccessStream* stream, Long stride)
171	{
172	   UInt i;
173	
174	   for (i = 0; i < stream->n_strides; i++) {
175	      if (stream->strides[i].stride == stride) {
176	         stream->strides[i].count++;
177	         return;
178	      }
179	   }
180	
181	   if (stream->n_strides < N_STRIDE_BINS) {
182	      stream->strides[stream->n_strides].stride = stride;
183	      stream->strides[stream->n_strides].count = 1;
184	      stream->n_strides++;
185	   } else {
186	      UInt least = least_frequent_stride_index(stream);
187	      if (stream->strides[least].count == 1) {
188	         stream->strides[least].stride = stride;
189	      } else {
