203	static void update_stream(AccessStream* stream, Addr addr, SizeT size)
204	{
205	   stream->accesses++;
206	
207	   if (!stream->have_prev) {
208	      stream->prev_addr = addr;
209	      stream->have_prev = True;
210	      return;
211	   }
212	
213	   {
214	      Long stride = addr_delta(addr, stream->prev_addr);
215	
216	      stream->stride_samples++;
217	      if (stride == (Long)size || stride == -(Long)size) {
218	         stream->sequential_steps++;
219	      }
220	      add_stride_sample(stream, stride);
221	      stream->prev_addr = addr;
222	   }
223	}
