225	static void finish_stream(AccessStream* stream)
226	{
227	   UInt i;
228	   ULong dominant_count = 0;
229	
230	   stream->pattern = Pattern_None;
231	   stream->dominant_stride = 0;
232	
233	   if (stream->stride_samples == 0) {
234	      return;
235	   }
236	
237	   for (i = 0; i < stream->n_strides; i++) {
238	      if (stream->strides[i].count > dominant_count) {
239	         dominant_count = stream->strides[i].count;
240	         stream->dominant_stride = stream->strides[i].stride;
241	      }
242	   }
243	
244	   if ((100.0 * stream->sequential_steps / stream->stride_samples)
245	       >= clo_sequential_threshold) {
246	      stream->pattern = Pattern_Sequential;
247	   } else if ((100.0 * dominant_count / stream->stride_samples)
248	              >= clo_sequential_threshold) {
