471	                                sizeofIRType(type),
472	                                NULL);
473	            }
474	            addStmtToIRSB(sbOut, st);
475	            break;
476	         }
477	
478	         case Ist_Exit:
479	            addStmtToIRSB(sbOut, st);
480	            break;
481	
482	         default:
483	            ppIRStmt(st);
484	            tl_assert(0);
485	      }
486	   }
