467	                            cas->addr, size, NULL);
468	            instrument_store(sbOut, current_stats,
469	                             cas->addr, size, NULL);
470	            addStmtToIRSB(sbOut, st);
471	            break;
472	         }
473	
474	         case Ist_LLSC: {
475	            IRType type;
476	            if (st->Ist.LLSC.storedata == NULL) {
477	               type = typeOfIRTemp(tyenv, st->Ist.LLSC.result);
478	               instrument_load(sbOut, current_stats,
479	                               st->Ist.LLSC.addr,
480	                               sizeofIRType(type),
