   378	
   379	   for (; i < sbIn->stmts_used; i++) {
   380	      IRStmt* st = sbIn->stmts[i];
   381	
   382	      if (st == NULL || st->tag == Ist_NoOp) {
   383	         continue;
   384	      }
   385	
   386	      switch (st->tag) {
