   394	         case Ist_IMark:
   395	            current_stats = get_function_stats(st->Ist.IMark.addr);
   396	            addStmtToIRSB(sbOut, st);
   397	            break;
   398	
   399	         case Ist_WrTmp: {
   400	            IRExpr* expr = st->Ist.WrTmp.data;
   401	            if (expr->tag == Iex_Load) {
   402	               instrument_load(sbOut, current_stats,
