   408	            break;
   409	         }
   410	
   411	         case Ist_Store: {
   412	            IRType type = typeOfIRExpr(tyenv, st->Ist.Store.data);
   413	            instrument_store(sbOut, current_stats,
   414	                             st->Ist.Store.addr,
   415	                             sizeofIRType(type),
   416	                             NULL);
   417	            addStmtToIRSB(sbOut, st);
   418	            break;
   419	         }
   420	
   421	         case Ist_StoreG: {
   422	            IRStoreG* store = st->Ist.StoreG.details;
   423	            IRType type = typeOfIRExpr(tyenv, store->data);
   424	            instrument_store(sbOut, current_stats,
   425	                             store->addr,
   426	                             sizeofIRType(type),
   427	                             store->guard);
   428	            addStmtToIRSB(sbOut, st);
   429	            break;
   430	         }
   431	
   432	         case Ist_LoadG: {
   433	            IRLoadG* load = st->Ist.LoadG.details;
   434	            IRType type = Ity_INVALID;
   435	            IRType wide_type = Ity_INVALID;
   436	            typeOfIRLoadGOp(load->cvt, &wide_type, &type);
   437	            instrument_load(sbOut, current_stats,
   438	                            load->addr,
   439	                            sizeofIRType(type),
   440	                            load->guard);
   441	            addStmtToIRSB(sbOut, st);
   442	            break;
   443	         }
   444	
   445	         case Ist_Dirty: {
   446	            IRDirty* dirty = st->Ist.Dirty.details;
   447	            if (dirty->mFx == Ifx_Read || dirty->mFx == Ifx_Modify) {
   448	               instrument_load(sbOut, current_stats,
   449	                               dirty->mAddr, dirty->mSize, dirty->guard);
   450	            }
