   454	            }
   455	            addStmtToIRSB(sbOut, st);
   456	            break;
   457	         }
   458	
   459	         case Ist_CAS: {
   460	            IRCAS* cas = st->Ist.CAS.details;
   461	            IRType type = typeOfIRExpr(tyenv, cas->dataLo);
   462	            Int size = sizeofIRType(type);
   463	            if (cas->dataHi != NULL) {
   464	               size *= 2;
   465	            }
   466	            instrument_load(sbOut, current_stats,
   467	                            cas->addr, size, NULL);
   468	            instrument_store(sbOut, current_stats,
   469	                             cas->addr, size, NULL);
   470	            addStmtToIRSB(sbOut, st);
   471	            break;
   472	         }
   473	
   474	         case Ist_LLSC: {
   475	            IRType type;
   476	            if (st->Ist.LLSC.storedata == NULL) {
   477	               type = typeOfIRTemp(tyenv, st->Ist.LLSC.result);
